// Sign-in of the web app (generated by gherkin-ai): POST /api/v1/auth/login issues the bearer token every API client sends.

const KEY = 'ghk.session';

export interface Session {
  token: string;
  user: { id: string; email: string; name?: string; tenantId: string; roles: string[]; permissions: string[] };
}

const storage = (): Storage | undefined => (typeof localStorage === 'undefined' ? undefined : localStorage);

export function currentSession(): Session | undefined {
  try {
    const raw = storage()?.getItem(KEY);
    return raw ? (JSON.parse(raw) as Session) : undefined;
  } catch {
    return undefined;
  }
}

/** The bearer token of the signed-in user (undefined when nobody is signed in). */
export const currentToken = (): string | undefined => currentSession()?.token;

export function signOut(): void {
  storage()?.removeItem(KEY);
}

async function post(path: string, body: unknown, doFetch: (input: string, init?: RequestInit) => Promise<Response>): Promise<Record<string, unknown>> {
  const res = await doFetch(path, { method: 'POST', headers: { 'Content-Type': 'application/json', Accept: 'application/json' }, body: JSON.stringify(body) });
  const json = (await res.json().catch(() => ({}))) as Record<string, unknown>;
  if (!res.ok) throw new Error(String(json.message ?? json.detail ?? json.title ?? `Request failed with status ${res.status}`));
  return json;
}

export async function signIn(email: string, password: string, options: { tenant?: string; baseUrl?: string; fetch?: typeof fetch } = {}): Promise<Session> {
  const doFetch = options.fetch ?? ((...args: Parameters<typeof fetch>) => fetch(...args));
  const body = await post(`${options.baseUrl ?? ''}/api/v1/auth/login`, { email, password, ...(options.tenant ? { tenant: options.tenant } : {}) }, doFetch);
  const session = { token: String(body.token), user: body.user as Session['user'] };
  storage()?.setItem(KEY, JSON.stringify(session));
  return session;
}

export async function register(input: { email: string; password: string; name?: string; tenant?: string }, options: { baseUrl?: string; fetch?: typeof fetch } = {}): Promise<Record<string, unknown>> {
  const doFetch = options.fetch ?? ((...args: Parameters<typeof fetch>) => fetch(...args));
  return post(`${options.baseUrl ?? ''}/api/v1/auth/register`, input, doFetch);
}
